class C2ExpertCourseData {
 static List<String> _rotate(List<String> v,int a)=>List<String>.generate(v.length,(i)=>v[(i-a+v.length)%v.length]);
 static B1Question _q(String p,List<String> o,int a,String e)=>B1Question(p,_rotate(o,a),a,e);
 static B1Lesson _build(_Spec s){final n=s.number;final w=[s.meaning,'التعبير عن المكان','التعبير عن الزمن الماضي','طلب الإذن'];final tr=[s.translation,'لم يبدأ الاجتماع بعد.','سأعود إلى المنزل غداً.','لا تتضمن الجملة هذا المعنى.'];final fm=[s.form,'geçmiş zaman','istek kipi','yer tamlayıcısı'];final fn=[s.functionText,'تحديد المكان فقط','تغيير زمن الجملة فقط','تكوين سؤال عن السعر'];return B1Lesson(unitId:s.unitId,globalNumber:n,title:s.title,goal:s.goal,rule:s.rule,examples:[s.sentence+' | '+s.translation,s.example],dialogue:s.dialogue,speakingTask:s.task,questions:[_q('ما معنى «${s.term}»؟',w,n%4,'«${s.term}» تعني: ${s.meaning}.'),_q('ما ترجمة الجملة التركية؟',tr,(n+1)%4,s.translation),_q('أي تعبير يرتبط بمهارة الدرس؟',fm,(n+2)%4,'التعبير المستهدف «${s.form}». '+s.rule),_q('ما الوظيفة التواصلية الأساسية؟',fn,(n+3)%4,s.functionText),_q('أي ممارسة تثبت إتقان المهارة؟',[s.task,'حفظ كلمات دون سياق','نسخ نص دون فهم','تجاهل القرائن والأدلة'],(n+1)%4,s.task)]);}
 static final List<B1Lesson> lessons=[
_Spec(unitId:'c2-u4',number:451,title:'تفكيك الخطاب السياسي المعقد',goal:'تحليل الأطر والافتراضات واللغة الإقناعية في الخطاب السياسي.',rule:'افصل مضمون الادعاء عن طريقة تأطيره، وحدد الجمهور والمصلحة والافتراضات.',term:'siyasal çerçeveleme',meaning:'تأطير سياسي',sentence:'Konuşma, aynı politikayı güvenlik ve özgürlük kavramlarıyla farklı biçimde sunuyor.',translation:'يعرض الخطاب السياسة نفسها بصورتين مختلفتين عبر مفهومي الأمن والحرية.',form:'siyasal söylem çözümlemesi',functionText:'تحليل التأطير واللغة السياسية.',task:'حلل خطاباً سياسياً وحدد ثلاثة أطر ونتائجها على المتلقي.',example:'Söylemin çerçevesini ve varsayımlarını ayırdım.|فصلت إطار الخطاب وافتراضاته.',dialogue:'A: Hangi kavram öne çıkarılıyor؟ — أي مفهوم يجري إبرازه؟\nB: Güvenlik vurgusu, diğer boyutları geri plana itiyor. — يضع التركيز على الأمن الأبعاد الأخرى في الخلفية.'),
_Spec(unitId:'c2-u4',number:452,title:'تحليل السلطة والهوية في اللغة',goal:'تفسير كيفية بناء الهوية والعلاقات الاجتماعية من خلال الاختيارات اللغوية.',rule:'راقب الضمائر والتسميات والألقاب ومن يملك حق الكلام وكيف توزع المسؤولية.',term:'kimlik inşası',meaning:'بناء الهوية',sentence:'Kullanılan adlandırmalar, grupların kamusal kimliğini etkiliyor.',translation:'تؤثر التسميات المستخدمة في الهوية العامة للمجموعات.',form:'dil ve güç ilişkisi',functionText:'تحليل علاقة اللغة بالسلطة والهوية.',task:'قارن خطابين في وصف المجموعة نفسها وحدد أثر التسمية.',example:'Dilsel tercihlerin kimlik algısını nasıl şekillendirdiğini inceledim.|درست كيف تشكل الاختيارات اللغوية إدراك الهوية.',dialogue:'A: Sözcük seçimi tarafsız mı؟ — هل اختيار الكلمات محايد؟\nB: Her zaman değil; bazı adlandırmalar güç ilişkilerini yansıtıyor. — ليس دائماً؛ بعض التسميات تعكس علاقات القوة.'),
_Spec(unitId:'c2-u4',number:453,title:'تحليل الاستعارة المفاهيمية',goal:'كشف الاستعارات التي تنظم التفكير في موضوع مجرد.',rule:'حدد المجال المصدر والهدف، ثم اختبر كيف توجه الاستعارة فهم القضية وما الذي تخفيه.',term:'kavramsal metafor',meaning:'استعارة مفاهيمية',sentence:'Tartışma, ekonomiyi bir yarış olarak çerçeveliyor.',translation:'يؤطر النقاش الاقتصاد بوصفه سباقاً.',form:'kavramsal eşleme',functionText:'تحليل الاستعارة التي تنظم تصور المفهوم.',task:'استخرج استعارتين مفاهيميتين من مقال واشرح أثرهما.',example:'Kavramsal eşlemeyi metindeki örneklerle açıkladım.|شرحت المطابقة المفاهيمية بأمثلة من النص.',dialogue:'A: Bu yalnızca süslü bir ifade mi؟ — هل هو مجرد تعبير مزخرف؟\nB: Hayır, düşünme biçimini de yönlendiriyor. — لا، إنه يوجه طريقة التفكير أيضاً.'),
_Spec(unitId:'c2-u4',number:454,title:'تقييم الحجج الأخلاقية',goal:'تحليل القيم والمبادئ التي تقوم عليها حجة أخلاقية.',rule:'حدد المبدأ الأخلاقي والجهات المتأثرة والتعارض بين القيم ثم ناقش الموازنة.',term:'etik gerekçe',meaning:'مبرر أخلاقي',sentence:'Kararın adil olup olmadığı, yalnızca sonucuna değil ilkesine de bağlıdır.',translation:'لا يتوقف عدل القرار على نتيجته فحسب بل على مبدئه أيضاً.',form:'etik argümantasyon',functionText:'تحليل المبررات والقيم الأخلاقية.',task:'حلل قضية أخلاقية وحدد قيمتين متعارضتين وحجة لكل منهما.',example:'Etik ilkeleri ve olası sonuçları birlikte değerlendirdim.|قيّمت المبادئ الأخلاقية والنتائج المحتملة معاً.',dialogue:'A: En önemli ölçüt sonuç mu؟ — هل النتيجة هي المعيار الأهم؟\nB: İlke, haklar ve sonuç birlikte ele alınmalı. — ينبغي تناول المبدأ والحقوق والنتيجة معاً.'),
_Spec(unitId:'c2-u4',number:455,title:'التمييز بين الخطأ المنطقي والمغالطة',goal:'كشف الخلل في بنية الحجة وعدم الخلط بين ضعف الدليل والمغالطة.',rule:'حدد شكل الاستدلال، وافحص صلة المقدمات، وميز التعميم المتسرع والشخصنة والثنائية الزائفة.',term:'mantık yanılgısı',meaning:'مغالطة منطقية',sentence:'Bir iddianın sahibini eleştirmek, iddianın kendisini çürütmez.',translation:'انتقاد صاحب الادعاء لا يدحض الادعاء نفسه.',form:'safsata çözümlemesi',functionText:'تحديد المغالطات وتفسير أثرها.',task:'استخرج أربع مغالطات من نقاش واشرح موضع الخلل.',example:'Mantık hatasını örnek üzerinden gösterdim.|أوضحت الخطأ المنطقي من خلال مثال.',dialogue:'A: Konuşmacının güvenilir olmaması iddiayı çürütür mü؟ — هل عدم موثوقية المتحدث يدحض الادعاء؟\nB: Hayır, iddia ayrıca değerlendirilmelidir. — لا، ينبغي تقييم الادعاء بصورة مستقلة.'),
_Spec(unitId:'c2-u4',number:456,title:'التحليل المقارن للخطاب الإعلامي',goal:'مقارنة مصادر إعلامية في اختيار المصادر والتأطير وترتيب المعلومات.',rule:'قارن العناوين والصور والاقتباسات والمعلومات الغائبة، ثم اربط الفروق بسياسة التحرير.',term:'medya çerçevesi',meaning:'إطار إعلامي',sentence:'İki yayın, aynı olayı farklı kaynaklara ve başlıklara dayanarak aktarıyor.',translation:'تنقل وسيلتان الحدث نفسه اعتماداً على مصادر وعناوين مختلفة.',form:'karşılaştırmalı medya analizi',functionText:'مقارنة التأطير الإعلامي وانتقاء المعلومات.',task:'حلل تغطيتين لحدث واحد وحدد الفروق التحريرية.',example:'Haberlerin kaynak ve çerçeve tercihlerini karşılaştırdım.|قارنت اختيارات المصادر والتأطير في الأخبار.',dialogue:'A: Hangisi daha tarafsız؟ — أيهما أكثر حياداً؟\nB: Önce kullandıkları kaynakları ve eksik bıraktıklarını inceleyelim. — لنفحص أولاً مصادرهما وما أغفلتاه.'),
_Spec(unitId:'c2-u4',number:457,title:'الاستدلال من الأدلة المتعارضة',goal:'تكوين حكم متوازن عندما تشير الأدلة إلى اتجاهات مختلفة.',rule:'افصل جودة كل دليل وسياقه، وابحث عن اختلاف العينة أو التعريف أو الزمن قبل الترجيح.',term:'çelişen kanıt',meaning:'دليل متعارض',sentence:'Çelişen bulgular, ölçüm yöntemlerinin yeniden incelenmesini gerektiriyor.',translation:'تتطلب النتائج المتعارضة إعادة فحص أساليب القياس.',form:'kanıtları uzlaştırmak',functionText:'تفسير التعارض بين الأدلة قبل الاستنتاج.',task:'قارن ثلاث نتائج متعارضة واقترح تفسيراً منهجياً.',example:'Çelişen verileri tek bir sonuca zorlamadım.|لم أجبر البيانات المتعارضة على نتيجة واحدة.',dialogue:'A: Hangi bulguya güvenelim؟ — أي نتيجة نثق بها؟\nB: Önce yöntem ve örneklem farklarını karşılaştıralım. — لنقارن أولاً اختلافات المنهج والعينة.'),
_Spec(unitId:'c2-u4',number:458,title:'صياغة أطروحة أصلية متقدمة',goal:'إنتاج أطروحة تضيف تفسيراً أو تركيباً جديداً بدلاً من إعادة عرض المصادر.',rule:'حدد الفجوة، وصغ دعوى قابلة للنقاش، ثم وضح ما تضيفه إلى النقاش القائم.',term:'özgün tez',meaning:'أطروحة أصيلة',sentence:'Bu çalışma, mevcut yaklaşımları birleştiren yeni bir açıklama öneriyor.',translation:'يقترح هذا العمل تفسيراً جديداً يجمع المقاربات الحالية.',form:'özgün katkı',functionText:'صياغة مساهمة فكرية جديدة.',task:'اكتب أطروحة أصلية وبيّن اختلافها عن ثلاثة مواقف منشورة.',example:'Özgün katkımı önceki çalışmalarla karşılaştırdım.|قارنت إسهامي الأصيل بالدراسات السابقة.',dialogue:'A: Bu görüş daha önce savunulmuş mu؟ — هل سبق الدفاع عن هذا الرأي؟\nB: Benzer yönleri var, ancak sentez biçimi farklı. — توجد جوانب مشابهة لكن طريقة التركيب مختلفة.'),
_Spec(unitId:'c2-u4',number:459,title:'كتابة نقد خطابي متخصص',goal:'إنتاج نقد يستند إلى تحليل اللغة والبنية والسياق والأثر.',rule:'اربط كل حكم بقرينة نصية، وميز الوصف من التقييم، وتجنب نسبة نية غير مثبتة.',term:'söylem eleştirisi',meaning:'نقد الخطاب',sentence:'Eleştiri, kullanılan dilin hangi varsayımları doğal gösterdiğini sorguluyor.',translation:'يتساءل النقد عن الافتراضات التي تجعلها اللغة تبدو طبيعية.',form:'eleştirel söylem',functionText:'نقد الخطاب بالأدلة والسياق.',task:'اكتب نقداً لخطاب متخصص يوازن بين الأثر والحدود.',example:'Eleştirimi metinsel ve bağlamsal kanıtlarla destekledim.|دعمت نقدي بأدلة نصية وسياقية.',dialogue:'A: Konuşmacının niyetini biliyor muyuz؟ — هل نعرف نية المتحدث؟\nB: Niyet atfetmeden dilsel etkiyi inceleyebiliriz. — يمكننا دراسة الأثر اللغوي دون افتراض النية.'),
_Spec(unitId:'c2-u4',number:460,title:'مشروع التحليل النقدي للخطاب',goal:'دمج التحليل السياسي والإعلامي والأخلاقي والمنطقي في دراسة واحدة.',rule:'اختر مجموعة نصوص، وحدد إطار التحليل، واجمع الشواهد، وقدم نتائج وحدوداً.',term:'eleştirel söylem projesi',meaning:'مشروع نقد الخطاب',sentence:'Farklı metinleri ortak ölçütlerle inceleyip sonuçları raporladım.',translation:'درست نصوصاً مختلفة بمعايير مشتركة وقدمت النتائج في تقرير.',form:'bütünleşik söylem analizi',functionText:'إنتاج تحليل نقدي شامل.',task:'أنجز دراسة من 700 كلمة وعرضاً يوضح المنهج والنتائج.',example:'Projemde söylem, kanıt ve bağlam ilişkisini gösterdim.|أوضحت في مشروعي العلاقة بين الخطاب والدليل والسياق.',dialogue:'A: Çalışmanın kapsamı neydi؟ — ما نطاق الدراسة؟\nB: Üç farklı metin türünün karşılaştırılması. — مقارنة ثلاثة أنواع مختلفة من النصوص.'),
_Spec(unitId:'c2-u5',number:461,title:'التحرير البنيوي للنصوص الطويلة',goal:'إعادة بناء ترتيب الأفكار والحجج على مستوى العمل الكامل.',rule:'راجع منطق الأقسام أولاً ثم تسلسل الفقرات والإحالات قبل تحرير الجمل.',term:'yapısal editörlük',meaning:'تحرير بنيوي',sentence:'Bölümlerin sırasını değiştirerek argümanın gelişimini daha görünür kıldım.',translation:'جعلت تطور الحجة أوضح بتغيير ترتيب الأقسام.',form:'metin mimarisi',functionText:'تحسين هندسة النص وبنيته.',task:'حرر تقريراً طويلاً بإعادة ترتيب الأقسام وتبرير كل تعديل.',example:'Metnin yapısını ana savın gelişimine göre düzenledim.|نظمت بنية النص وفق تطور الحجة الرئيسة.',dialogue:'A: İlk olarak hangi düzeyi gözden geçirdin؟ — أي مستوى راجعت أولاً؟\nB: Bölümlerin mantıksal sırasını. — الترتيب المنطقي للأقسام.'),
_Spec(unitId:'c2-u5',number:462,title:'إدارة المصطلحات في مشروع ترجمة',goal:'بناء قاعدة مصطلحات موحدة لمشروع طويل متعدد المشاركين.',rule:'حدد التعريف والمقابل والسياق والبدائل المرفوضة، وراجع الاتساق عبر جميع الملفات.',term:'terim yönetimi',meaning:'إدارة المصطلحات',sentence:'Terim tabanını ekipçe güncelleyip bütün bölümlerde aynı karşılıkları kullandık.',translation:'حدثنا قاعدة المصطلحات جماعياً واستخدمنا المقابلات نفسها في جميع الأقسام.',form:'terim birliği',functionText:'ضمان اتساق المصطلحات في المشروع.',task:'أنشئ مسرداً من 30 مصطلحاً مع تعريف وسياق ومقابل تركي عربي.',example:'Terim tercihlerini ortak bir sözlükte topladım.|جمعت اختيارات المصطلحات في معجم مشترك.',dialogue:'A: Her çevirmen kendi karşılığını seçebilir mi؟ — هل يختار كل مترجم مقابله؟\nB: Önceden belirlenen terim politikasına uymalı. — ينبغي الالتزام بسياسة المصطلحات المحددة مسبقاً.'),
_Spec(unitId:'c2-u5',number:463,title:'مراجعة الأمانة العلمية والتوثيق',goal:'التحقق من نسبة الأفكار والاقتباسات والبيانات إلى مصادرها.',rule:'راجع كل اقتباس وإعادة صياغة وبيانات، وميز المعرفة العامة عن المساهمة الأصلية.',term:'akademik dürüstlük',meaning:'الأمانة الأكاديمية',sentence:'Her iddia ve alıntı için uygun kaynak gösterdim.',translation:'أشرت إلى مصدر مناسب لكل ادعاء واقتباس.',form:'atıf denetimi',functionText:'ضمان دقة الإسناد والتوثيق.',task:'دقق مقالاً بحثياً وابحث عن خمسة مواضع تحتاج إلى توثيق.',example:'Atıfları kaynaklarla tek tek karşılaştırdım.|قارنت الإحالات بالمصادر واحدة تلو الأخرى.',dialogue:'A: Yeniden ifade edilen fikir de kaynak ister mi؟ — هل تحتاج الفكرة المعاد صياغتها إلى مصدر؟\nB: Evet, fikir başkasına aitse belirtilmeli. — نعم، إذا كانت الفكرة لشخص آخر فيجب الإشارة إليه.'),
_Spec(unitId:'c2-u5',number:464,title:'تحرير الملخصات متعددة التخصصات',goal:'صياغة ملخص مفهوم للخبراء من مجالات مختلفة.',rule:'عرف المصطلحات الضرورية، واحذف التفاصيل الخاصة بتخصص واحد، وأبرز النتائج العابرة للتخصصات.',term:'disiplinlerarası özet',meaning:'ملخص متعدد التخصصات',sentence:'Özeti farklı alanlardan araştırmacıların anlayabileceği biçimde yeniden yazdım.',translation:'أعدت كتابة الملخص بطريقة يفهمها باحثون من مجالات مختلفة.',form:'disiplinlerarası anlatım',functionText:'تكييف الملخص لجمهور متعدد التخصصات.',task:'اكتب ملخصاً من 200 كلمة موجهاً لخبراء من ثلاثة تخصصات.',example:'Özette ortak kavramları ve temel sonucu öne çıkardım.|أبرزت المفاهيم المشتركة والنتيجة الأساسية في الملخص.',dialogue:'A: Teknik ayrıntıları tamamen çıkaralım mı؟ — هل نحذف التفاصيل التقنية كلها؟\nB: Yalnızca farklı alanlar için gerekli olmayanları. — فقط ما لا يلزم للمجالات الأخرى.'),
_Spec(unitId:'c2-u5',number:465,title:'التحرير وفق دليل أسلوبي',goal:'تطبيق قواعد موحدة للنبرة والمصطلحات والترقيم والإحالات.',rule:'حوّل دليل الأسلوب إلى قائمة تحقق وطبقها آلياً وبشرياً على كامل النص.',term:'stil kılavuzu',meaning:'دليل أسلوبي',sentence:'Tüm yazarlar aynı stil kılavuzuna göre metni düzenledi.',translation:'حرر جميع الكتّاب النص وفق دليل الأسلوب نفسه.',form:'editoryal standart',functionText:'توحيد معايير التحرير.',task:'أنشئ صفحة دليل أسلوب وطبقها على مقالين مختلفين.',example:'Stil birliğini belge boyunca korudum.|حافظت على وحدة الأسلوب في الوثيقة.',dialogue:'A: Küçük biçim farkları önemli mi؟ — هل الفروق الشكلية الصغيرة مهمة؟\nB: Yayın bütünlüğü için tutarlılık gerekir. — الاتساق ضروري لوحدة النشر.'),
_Spec(unitId:'c2-u5',number:466,title:'إدارة دورة مراجعة المخطوط',goal:'تنظيم المراجعات المتتابعة وتوثيق التغييرات والقرارات.',rule:'حدد النسخ والمواعيد والمسؤولين، وافصل الملاحظات الجوهرية عن التحرير الشكلي.',term:'revizyon döngüsü',meaning:'دورة المراجعة',sentence:'Her revizyonda değişiklikleri ve gerekçelerini ayrı kaydettik.',translation:'سجلنا التعديلات ومبرراتها بصورة منفصلة في كل مراجعة.',form:'sürüm kontrolü',functionText:'إدارة نسخ النص والتعديلات.',task:'صمم دورة مراجعة من ثلاث مراحل مع سجل قرارات.',example:'Revizyonları sürüm numaralarıyla izledim.|تابعت المراجعات بأرقام النسخ.',dialogue:'A: Eski sürümü saklayalım mı؟ — هل نحتفظ بالنسخة القديمة؟\nB: Evet, değişiklikleri karşılaştırmak için gerekli. — نعم، فهي ضرورية لمقارنة التعديلات.'),
_Spec(unitId:'c2-u5',number:467,title:'كتابة مقدمة بحثية متقدمة',goal:'بناء مقدمة تعرض المشكلة والفجوة والسؤال والإسهام.',rule:'انتقل من المجال العام إلى المشكلة المحددة، ثم أبرز الفجوة وهدف الدراسة وإسهامها.',term:'araştırma boşluğu',meaning:'فجوة بحثية',sentence:'Önceki çalışmaların sınırlı bıraktığı noktayı açıkça tanımladım.',translation:'حددت بوضوح النقطة التي تركتها الدراسات السابقة دون معالجة كافية.',form:'giriş bölümü',functionText:'بناء مقدمة تبرر ضرورة البحث.',task:'اكتب مقدمة من أربع فقرات لمشروع بحثي مع تحديد الفجوة.',example:'Araştırma boşluğunu kaynaklarla temellendirdim.|أسست الفجوة البحثية بالمصادر.',dialogue:'A: Konuyu nasıl daralttın؟ — كيف ضيقت الموضوع؟\nB: Literatürde yanıtlanmamış soruyu belirleyerek. — بتحديد السؤال الذي لم تجب عنه الأدبيات.'),
_Spec(unitId:'c2-u5',number:468,title:'كتابة خاتمة تركيبية',goal:'صياغة خاتمة لا تكرر المقدمة بل تستخلص دلالة النتائج وحدودها.',rule:'اربط النتائج بالسؤال الأصلي، وحدد ما تغير في الفهم، واقترح مساراً لاحقاً.',term:'sentezleyici sonuç',meaning:'خاتمة تركيبية',sentence:'Sonuç, bulguları araştırma sorusuna geri bağlayarak yorumluyor.',translation:'تفسر الخاتمة النتائج بربطها مجدداً بسؤال البحث.',form:'sonuç sentezi',functionText:'تركيب النتائج والدلالات والحدود.',task:'اكتب خاتمة تذكر الإسهام والحدود وسؤالاً لاحقاً.',example:'Sonuç bölümünde yeni bir iddia eklemeden bulguları sentezledim.|ركبت النتائج في الخاتمة دون إضافة ادعاء جديد.',dialogue:'A: Sonuçta yeni veri sunmalı mıyız؟ — هل نقدم بيانات جديدة في الخاتمة؟\nB: Hayır, mevcut bulguların anlamını açıklamalıyız. — لا، ينبغي شرح معنى النتائج الحالية.'),
_Spec(unitId:'c2-u5',number:469,title:'إعداد ملف النشر النهائي',goal:'تجهيز المخطوط والملخص والمراجع والملفات وفق متطلبات جهة النشر.',rule:'استخدم قائمة المتطلبات، وتحقق من التنسيق والبيانات الوصفية والمرفقات وحقوق الاستخدام.',term:'yayın dosyası',meaning:'ملف النشر',sentence:'Gönderim dosyasındaki tüm belgeleri yayın yönergesine göre kontrol ettim.',translation:'تحققت من جميع وثائق ملف الإرسال وفق إرشادات النشر.',form:'gönderim hazırlığı',functionText:'تجهيز وثائق النشر ومرفقاته.',task:'جهز حزمة تقديم لمجلة تشمل المقال والملخص والمراجع والبيانات المطلوبة.',example:'Yayın dosyasını eksiksiz biçimde hazırladım.|جهزت ملف النشر بصورة كاملة.',dialogue:'A: Son kontrol listesinde neler var؟ — ماذا تتضمن قائمة التحقق الأخيرة؟\nB: Biçim, kaynakça, ekler ve yazar bilgileri. — التنسيق والمراجع والمرفقات ومعلومات المؤلف.'),
_Spec(unitId:'c2-u5',number:470,title:'مشروع التحرير والنشر المتقدم',goal:'إدارة نص من المسودة إلى نسخة صالحة للتقديم.',rule:'اجمع التحرير البنيوي والمصطلحي والتوثيق ومراجعة النسخ والملخص النهائي.',term:'yayına hazırlık projesi',meaning:'مشروع إعداد للنشر',sentence:'Metni ekipçe düzenleyip son sürümü yayın ölçütlerine göre hazırladık.',translation:'حررنا النص جماعياً وجهزنا نسخته النهائية وفق معايير النشر.',form:'editoryal proje',functionText:'إدارة مشروع تحرير ونشر متكامل.',task:'أكمل مشروعاً يتضمن مسودة ومراجعتين وملف نشر نهائي.',example:'Editoryal kararları ve son değişiklikleri belgeledim.|وثقت القرارات التحريرية والتعديلات النهائية.',dialogue:'A: Kim son onayı verecek؟ — من سيمنح الموافقة النهائية؟\nB: Sorumlu editör, kontrol listesini tamamladıktan sonra. — المحرر المسؤول بعد إكمال قائمة التحقق.'),
_Spec(unitId:'c2-u6',number:471,title:'إدارة مفاوضات متعددة الأطراف',goal:'إدارة مصالح متعارضة بين عدة أطراف وصياغة مسار تفاوضي.',rule:'حدد الأطراف والمصالح والقيود والبدائل، ثم رتب القضايا حسب إمكانية الاتفاق.',term:'çok taraflı müzakere',meaning:'تفاوض متعدد الأطراف',sentence:'Tarafların önceliklerini ayrı ayrı belirleyip ortak seçenekler geliştirdik.',translation:'حددنا أولويات الأطراف بصورة منفصلة وطوّرنا خيارات مشتركة.',form:'müzakere mimarisi',functionText:'بناء عملية تفاوض متعددة الأطراف.',task:'صمم خطة تفاوض لأربعة أطراف مع خريطة مصالح وبدائل.',example:'Müzakere sürecini aşamalı bir plana bağladım.|ربطت عملية التفاوض بخطة مرحلية.',dialogue:'A: Herkes aynı önceliğe mi sahip؟ — هل لدى الجميع الأولوية نفسها؟\nB: Hayır, bu yüzden çıkarları ayrı analiz ettik. — لا، لذلك حللنا المصالح بصورة منفصلة.'),
_Spec(unitId:'c2-u6',number:472,title:'صياغة اتفاقات دقيقة',goal:'كتابة اتفاق يحدد الالتزامات والشروط والاستثناءات وآلية المتابعة.',rule:'استخدم مصطلحات محددة، وحدد المسؤول والموعد ومؤشر التنفيذ وإجراء معالجة الخلاف.',term:'mutabakat metni',meaning:'وثيقة تفاهم',sentence:'Anlaşmada sorumluluklar ve uygulama takvimi açıkça belirtildi.',translation:'وُضحت المسؤوليات والجدول التنفيذي في الاتفاق.',form:'anlaşma hükümleri',functionText:'صياغة التزامات قابلة للفهم والمتابعة.',task:'اكتب مسودة اتفاق بين مؤسستين تتضمن ستة بنود واضحة.',example:'Anlaşma maddelerini belirsizliğe yer bırakmadan yazdım.|كتبت بنود الاتفاق دون ترك مجال للغموض.',dialogue:'A: Bu madde yoruma açık mı؟ — هل هذا البند قابل لتفسيرات متعددة؟\nB: Sorumlu ve süreyi açıkça belirtmeliyiz. — ينبغي تحديد المسؤول والمدة بوضوح.'),
_Spec(unitId:'c2-u6',number:473,title:'التواصل في النزاعات الحساسة',goal:'إدارة لغة الحوار عندما تكون المصالح أو الهويات موضع خلاف.',rule:'استخدم لغة غير اتهامية، وميز الوقائع عن التقييم، واطلب التحقق من الفهم.',term:'gerilimi azaltmak',meaning:'خفض التوتر',sentence:'Önce ortak kaygıları belirleyerek görüşmenin tonunu yumuşattık.',translation:'خففنا نبرة الاجتماع بتحديد المخاوف المشتركة أولاً.',form:'çatışma iletişimi',functionText:'خفض التصعيد مع الحفاظ على وضوح الموقف.',task:'اكتب حواراً يعيد توجيه نقاش متوتر إلى نقاط قابلة للحل.',example:'Gerginliği artırmadan temel sorunu tanımladım.|حددت المشكلة الأساسية دون زيادة التوتر.',dialogue:'A: Bu suçlama mı؟ — هل هذا اتهام؟\nB: Hayır, durumu birlikte netleştirmeye çalışıyorum. — لا، أحاول توضيح الوضع معاً.'),
_Spec(unitId:'c2-u6',number:474,title:'التواصل بين الثقافات في المؤسسات',goal:'تكييف الرسائل والإجراءات مع اختلاف توقعات الفرق الدولية.',rule:'اسأل عن تفضيلات التواصل ولا تعتمد على الصور النمطية، ووثق الاتفاقات صراحة.',term:'kültürlerarası kurum iletişimi',meaning:'تواصل مؤسسي بين الثقافات',sentence:'Uluslararası ekipte karar ve geri bildirim beklentilerini açıkça konuştuk.',translation:'ناقشنا بوضوح توقعات القرار والتغذية الراجعة في الفريق الدولي.',form:'kültürlerarası uyum',functionText:'تنسيق أساليب التواصل بين فرق مختلفة.',task:'ضع بروتوكول تواصل لفريق دولي متعدد اللغات.',example:'İletişim tercihlerini varsaymak yerine doğrudan sordum.|سألت عن تفضيلات التواصل بدلاً من افتراضها.',dialogue:'A: Herkes aynı şekilde geri bildirim mi bekliyor؟ — هل يتوقع الجميع التغذية الراجعة بالطريقة نفسها؟\nB: Bunu ekip içinde netleştirmeliyiz. — ينبغي توضيح ذلك داخل الفريق.'),
_Spec(unitId:'c2-u6',number:475,title:'قيادة فريق بحثي متعدد التخصصات',goal:'توحيد عمل خبراء من مجالات مختلفة حول سؤال مشترك.',rule:'وضح المصطلحات والأدوار ومعايير الأدلة، وخصص مساحة للاختلاف المنهجي.',term:'disiplinlerarası ekip',meaning:'فريق متعدد التخصصات',sentence:'Her uzmanlık alanının katkısını ortak araştırma hedefiyle ilişkilendirdik.',translation:'ربطنا إسهام كل تخصص بهدف البحث المشترك.',form:'ortak çalışma çerçevesi',functionText:'تنسيق خبرات مختلفة ضمن مشروع واحد.',task:'صمم خطة قيادة لفريق من أربعة تخصصات مع مخرجات مشتركة.',example:'Disiplinler arası iletişimi ortak hedeflerle güçlendirdim.|عززت التواصل بين التخصصات بأهداف مشتركة.',dialogue:'A: Terimleri herkes aynı mı kullanıyor؟ — هل يستخدم الجميع المصطلحات نفسها؟\nB: Önce ortak bir kavram listesi oluşturalım. — لننشئ قائمة مفاهيم مشتركة أولاً.'),
_Spec(unitId:'c2-u6',number:476,title:'التعامل مع النقد العام والإعلامي',goal:'الرد على نقد علني مع حماية الدقة والشفافية والعلاقة.',rule:'اعترف بما ثبت، وصحح الخطأ، ووضح ما لم يتأكد، وحدد إجراء المتابعة.',term:'kamusal yanıt',meaning:'رد عام',sentence:'Eleştiriyi dikkate alıp doğrulanmış bilgileri kamuoyuyla paylaştık.',translation:'أخذنا النقد بعين الاعتبار وشاركنا المعلومات المتحقق منها مع الجمهور.',form:'şeffaf yanıt',functionText:'صياغة رد علني مسؤول.',task:'اكتب رداً عاماً على نقد يتضمن معلومة صحيحة وأخرى غير دقيقة.',example:'Yanıtımda doğrulama ve açıklık ilkesini korudum.|حافظت في ردي على مبدأ التحقق والوضوح.',dialogue:'A: Her eleştiriye hemen yanıt verelim mi؟ — هل نرد فوراً على كل نقد؟\nB: Önce bilgiyi doğrulayıp sonra açıklama yapalım. — لنتحقق من المعلومة أولاً ثم نصدر التوضيح.'),
_Spec(unitId:'c2-u6',number:477,title:'تصميم استراتيجية تواصل طويلة المدى',goal:'بناء خطة تواصل مستمرة ذات أهداف وجمهور ومؤشرات.',rule:'حدد الرسائل الأساسية والقنوات والمسؤوليات ومواعيد القياس والتحديث.',term:'iletişim stratejisi',meaning:'استراتيجية تواصل',sentence:'Strateji, hedef kitleleri ve başarı göstergelerini birlikte tanımlıyor.',translation:'تحدد الاستراتيجية الجمهور المستهدف ومؤشرات النجاح معاً.',form:'uzun vadeli planlama',functionText:'تخطيط التواصل وقياس أثره.',task:'أعد خطة تواصل لستة أشهر تتضمن أهدافاً ومؤشرات وقنوات.',example:'Stratejinin etkisini düzenli göstergelerle izledim.|تابعت أثر الاستراتيجية بمؤشرات منتظمة.',dialogue:'A: Başarıyı hangi aralıklarla ölçelim؟ — كل كم نقيس النجاح؟\nB: Üç ayda bir değerlendirme yapalım. — لنجر تقييماً كل ثلاثة أشهر.'),
_Spec(unitId:'c2-u6',number:478,title:'تقديم عرض استراتيجي لمجلس الإدارة',goal:'عرض خيارات وقرارات عالية الأثر بصورة موجزة ومقنعة.',rule:'قدم الخلاصة أولاً، ثم الخيارات والمخاطر والتكلفة والتوصية والقرار المطلوب.',term:'yönetim kurulu sunumu',meaning:'عرض لمجلس الإدارة',sentence:'Yönetim kuruluna üç seçenek ve bunların risklerini karşılaştırmalı sundum.',translation:'عرضت على مجلس الإدارة ثلاثة خيارات ومخاطرها بصورة مقارنة.',form:'stratejik karar sunumu',functionText:'دعم قرار إداري عالي الأثر.',task:'أعد عرضاً من خمس شرائح ينتهي بطلب قرار محدد.',example:'Sunumda kararın gerekçesini ve etkisini açıkça gösterdim.|أوضحت في العرض مبرر القرار وأثره.',dialogue:'A: Hangi seçeneği öneriyorsun؟ — أي خيار توصي به؟\nB: Risk ve etki dengesi en uygun olanı. — الخيار الأكثر توازناً بين المخاطر والأثر.'),
_Spec(unitId:'c2-u6',number:479,title:'تقييم أثر القيادة والتواصل',goal:'قياس أثر القرارات والرسائل على النتائج والثقة والتعاون.',rule:'اجمع مؤشرات كمية ونوعية، وقارنها بالهدف، وافصل أثر التدخل عن العوامل الأخرى.',term:'iletişim etkisi',meaning:'أثر التواصل',sentence:'Geri bildirimler, iletişim planının güven üzerindeki etkisini değerlendirmemizi sağladı.',translation:'أتاحت الملاحظات تقييم أثر خطة التواصل في الثقة.',form:'etki değerlendirmesi',functionText:'قياس أثر التواصل والقيادة.',task:'اكتب تقييماً بعد مشروع يضم ثلاثة مؤشرات ودرساً مستفاداً.',example:'İletişim sonuçlarını hedeflerle karşılaştırdım.|قارنت نتائج التواصل بالأهداف.',dialogue:'A: Yalnızca sayısal veriler yeterli mi؟ — هل تكفي البيانات الرقمية وحدها؟\nB: Nitel geri bildirimleri de incelemeliyiz. — ينبغي دراسة الملاحظات النوعية أيضاً.'),
_Spec(unitId:'c2-u6',number:480,title:'المشروع الختامي المتقدم لمستوى C2',goal:'إنتاج مشروع يبرهن على التحليل والكتابة والترجمة والقيادة والتواصل.',rule:'ادمج مصادر متعددة ومخرجات مكتوبة وشفهية، وقدم تقييماً ذاتياً قائماً على الأدلة.',term:'C2 bütünleşik proje',meaning:'مشروع متكامل لمستوى C2',sentence:'Projemde araştırma, editörlük ve stratejik iletişim becerilerini birleştirdim.',translation:'جمعت في مشروعي مهارات البحث والتحرير والتواصل الاستراتيجي.',form:'ileri uzmanlık projesi',functionText:'إثبات الكفاءة المتقدمة بمشروع أصيل.',task:'أنجز مشروعاً من تقرير وعرض وترجمة وخطة تواصل ومراجعة نقدية.',example:'C2 yetkinliğimi farklı görevlerle kanıtladım.|أثبت كفاءتي في C2 بمهام متنوعة.',dialogue:'A: Projenin kapsamı neden geniş؟ — لماذا نطاق المشروع واسع؟\nB: Farklı becerileri tek bir gerçekçi görevde birleştiriyor. — لأنه يجمع مهارات مختلفة في مهمة واقعية واحدة.'),
 ].map(_build).toList(growable:false);
}
